package dock

// In-memory registry of live polar-agent WebSocket connections.
// Maps bot_user_id → live agentConn. One bot may have at most one
// agent attached at a time; new connect kicks the old one off.
//
// This is the transport layer; the chat / ai_agent integration
// (where tool_call messages get generated by an LLM and routed
// here) lands in the next phase. For now there's a debug endpoint
// the user can hit to manually fire a tool_call and verify the
// round-trip.

import (
	"encoding/base64"
	"encoding/json"
	"errors"
	"sync"
	"time"
)

const (
	agentToolCallTimeout = 60 * time.Second
)

// agentToolCall is what the platform sends to a connected agent.
// id is a server-generated correlation token; the agent echoes it
// back in its agentToolResult so we can match the response.
type agentToolCall struct {
	Kind string         `json:"kind"` // always "tool_call"
	ID   string         `json:"id"`
	Tool string         `json:"tool"`
	Args map[string]any `json:"args"`
}

// agentToolResult is the agent's response. Echoes the call id.
type agentToolResult struct {
	Kind   string `json:"kind"` // "tool_result"
	ID     string `json:"id"`
	OK     bool   `json:"ok"`
	Stdout string `json:"stdout,omitempty"`
	Stderr string `json:"stderr,omitempty"`
	// Output is the shape-specific return (file content for read_file,
	// dir entries for list_dir, exit code for run_cmd). Tool-specific.
	Output map[string]any `json:"output,omitempty"`
	Error  string         `json:"error,omitempty"`
}

// agentConn is one live polar-agent. The receive loop dispatches
// incoming messages by Kind; pending tool calls + chat replies are
// each tracked separately so the platform can match responses to
// requests.
type agentConn struct {
	tokenID           string
	requestRemoteAddr string
	// attachedAt is set when the conn is registered with the hub.
	// Surfaces as `attached_at` on /api/agent/bots/:bot_id/status so
	// the UI can show "online for 2h 15m" / IP next to a connected bot.
	attachedAt time.Time
	userID     string
	botUserID  string
	// agentID — v4 logical agent identity (ag_<random32hex>); empty for
	// legacy v3 conns that pre-date the agents table. Used as the
	// primary hub key when non-empty so two agents on the same bot can
	// coexist (e.g. emei-kimi + emei-claude both pointing at the same
	// shared bot). See doc/arch/agent-identity-v4.md.
	agentID     string
	workspaceID string
	workdir    string
	// Capabilities the agent declared in its hello frame.
	// Recognized today:
	//   "tools"       — supports the tool_call/tool_result protocol
	//                   (read_file/write_file/list_dir/run_cmd)
	//   "passthrough" — wants chat_message envelopes routed verbatim;
	//                   replies via chat_reply
	//   "kimi"        — legacy alias, accepted for backward compat
	//                   with v1 polar-agent clients that only had
	//                   --kimi
	// Bots whose attached agent has neither passthrough nor kimi
	// stay on the platform tool_call loop.
	capabilities []string
	// tool is the passthrough tool name from the hello frame
	// ("kimi" / "claude" / "codex" / custom). Empty for tool-loop
	// agents. UI uses this to render the bot status badge text.
	tool string
	// hostID is the resolved hosts.id for this connection's agent
	// token, populated lazily on the first message that exercises the
	// host module. Empty when the token was created via the legacy
	// agent-tokens flow (no /api/hosts/register call). Cached here so
	// the WS dispatch doesn't hit the DB on every frame.
	hostID string
	send       chan []byte
	close      chan struct{}

	pendingMu sync.Mutex
	pending   map[string]chan agentToolResult

	chatPendingMu sync.Mutex
	chatPending   map[string]chan agentChatReply

	// skillPending is the per-run rendezvous for skill.event frames
	// (host module P1c.3). Each map entry is one in-flight skill.start
	// dispatch; the agent's skill.event frames keyed by run_id get
	// pushed onto the channel. The channel is buffered so state/log
	// events that arrive before the consumer drains don't block the WS
	// read loop. The consumer cleans up the map entry on exit.
	skillPendingMu sync.Mutex
	skillPending   map[int64]chan skillEventFrame

	// skillStdoutPending (P2 Shell): separate per-run byte channel for
	// `skill.event event_kind=stdout` frames. Decoupled from
	// skillPending so a slow xterm reader doesn't backpressure the
	// agent's lifecycle events. Larger buffer (256) — interactive
	// shell output is bursty. Overflow drops bytes with a logged
	// counter rather than blocking the WS read pump.
	skillStdoutMu      sync.Mutex
	skillStdoutPending map[int64]chan []byte

	// lastHostInfoSHA — sha256 of the most recent host_info payload
	// we forwarded to polar-hosts /internal/v1/hosts/hello. polar-dock#351.
	// A flapping agent reconnect would otherwise pummel the endpoint
	// with re-POSTs of identical static facts. Compared in
	// forwardHostInfoToPolarHosts; the forwarder writes through to here
	// on a successful POST. nil = nothing forwarded yet this conn.
	// Lifetime is the agentConn itself — when the WS closes the cache
	// is GC'd, so a brand-new conn always re-sends on first hello (we
	// can't trust a polar-hosts restart to remember). Per-conn rather
	// than per-host so two concurrent agents on the same host token
	// (rare but possible during a restart race) each refresh polar-hosts.
	lastHostInfoSHA []byte
}

func (c *agentConn) hasCapability(name string) bool {
	for _, cap := range c.capabilities {
		if cap == name {
			return true
		}
	}
	return false
}

// hasPassthrough returns true if the agent supports the
// chat_message/chat_reply passthrough protocol. Accepts either the
// new "passthrough" capability or the legacy "kimi" alias.
func (c *agentConn) hasPassthrough() bool {
	return c.hasCapability("passthrough") || c.hasCapability("kimi")
}

func (c *agentConn) trackPending(id string) chan agentToolResult {
	ch := make(chan agentToolResult, 1)
	c.pendingMu.Lock()
	c.pending[id] = ch
	c.pendingMu.Unlock()
	return ch
}

func (c *agentConn) deliverResult(r agentToolResult) {
	c.pendingMu.Lock()
	ch, ok := c.pending[r.ID]
	if ok {
		delete(c.pending, r.ID)
	}
	c.pendingMu.Unlock()
	if ok {
		ch <- r
	}
}

// agentChatMessage is the platform → agent envelope when routing a
// user-typed chat message into a passthrough agent. The agent
// spawns its local tool with Content as input and pipes stdout
// back as agentChatReply.
//
// WorkdirSubpath, when non-empty, scopes the tool's cwd to a
// subdirectory of the agent's pinned --workdir. Pickup handlers
// populate it with the project id so each project's code lives
// at $workdir/<project_id>/, isolated from other projects on
// the same agent. The agent mkdir -p's the path before exec.
type agentChatMessage struct {
	Kind           string `json:"kind"` // "chat_message"
	ID             string `json:"id"`
	ThreadID       int64  `json:"thread_id"`
	Content        string `json:"content"`
	WorkdirSubpath string `json:"workdir_subpath,omitempty"`
	// GitRemoteURL, when non-empty, tells the agent to do pre/post
	// git plumbing around the tool run: ensure repo + remote, then
	// commit + push everything the tool wrote, surface SHAs in the
	// reply. Phase 1 of the project pipeline Stage 5 (push code).
	GitRemoteURL string `json:"git_remote_url,omitempty"`
}

type agentChatReply struct {
	Kind    string `json:"kind"` // "chat_reply"
	ID      string `json:"id"`
	OK      bool   `json:"ok"`
	Content string `json:"content,omitempty"`
	Stderr  string `json:"stderr,omitempty"`
	Error   string `json:"error,omitempty"`
}

func (c *agentConn) trackChatPending(id string) chan agentChatReply {
	ch := make(chan agentChatReply, 1)
	c.chatPendingMu.Lock()
	c.chatPending[id] = ch
	c.chatPendingMu.Unlock()
	return ch
}

func (c *agentConn) deliverChatReply(r agentChatReply) {
	c.chatPendingMu.Lock()
	ch, ok := c.chatPending[r.ID]
	if ok {
		delete(c.chatPending, r.ID)
	}
	c.chatPendingMu.Unlock()
	if ok {
		ch <- r
	}
}

// agentHub owns the connection registry and the dispatch entry point.
// All methods are safe for concurrent use.
//
// v4 (doc/arch/agent-identity-v4.md): the hub now keys connections by
// agent_id when available (a new conn with the same bot but different
// agent_id no longer kicks the old one off — multiple agents can share
// a bot). Lookups still accept bot_user_id for back-compat with
// callers that haven't been threaded through yet; the bot-keyed map
// resolves to the *most-recently-attached* conn for that bot.
type agentHub struct {
	mu      sync.Mutex
	byAgent map[string]*agentConn // agent_id → conn (v4 primary)
	byBot   map[string]*agentConn // bot_user_id → conn (back-compat)
}

func newAgentHub() *agentHub {
	return &agentHub{
		byAgent: map[string]*agentConn{},
		byBot:   map[string]*agentConn{},
	}
}

// register adds a new connection. Behaviour:
//   - Same agent_id reconnects displace each other (last-write-wins).
//   - Different agent_id with same bot do NOT displace each other in
//     byAgent; the byBot map gets last-write-wins (legacy callers see
//     the most recent conn).
//   - Empty agent_id (legacy v3 attach) uses the bot id as the agent
//     key so the old "one bot, one conn" behaviour is preserved.
//
// Returns the displaced conn (if any) so the caller can close its
// socket cleanly.
func (h *agentHub) register(c *agentConn) *agentConn {
	h.mu.Lock()
	defer h.mu.Unlock()
	key := c.agentID
	if key == "" {
		key = c.botUserID
	}
	prev := h.byAgent[key]
	h.byAgent[key] = c
	h.byBot[c.botUserID] = c
	return prev
}

func (h *agentHub) unregister(c *agentConn) {
	h.mu.Lock()
	defer h.mu.Unlock()
	key := c.agentID
	if key == "" {
		key = c.botUserID
	}
	if cur, ok := h.byAgent[key]; ok && cur == c {
		delete(h.byAgent, key)
	}
	if cur, ok := h.byBot[c.botUserID]; ok && cur == c {
		delete(h.byBot, c.botUserID)
	}
}

// lookup resolves a key to a live conn. The key may be either an
// agent_id (v4) or a bot_user_id (legacy / dispatcher-side callers
// that only know the bot). agent_id wins when both maps would match
// because the byAgent map is the source of truth for v4 conns.
func (h *agentHub) lookup(key string) *agentConn {
	h.mu.Lock()
	defer h.mu.Unlock()
	if c, ok := h.byAgent[key]; ok {
		return c
	}
	return h.byBot[key]
}

// lookupByAgentID is the v4-only resolver — used by callers that know
// the agent_id and want to bypass the bot-fallback path.
func (h *agentHub) lookupByAgentID(agentID string) *agentConn {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.byAgent[agentID]
}

// snapshotByTool returns a count of currently-attached agents grouped
// by their declared tool flavor. Empty tool (= tool-loop mode bots)
// is mapped to "tool_loop" so the metric exposition has a stable
// non-empty label. Used by the metrics sampler.
func (h *agentHub) snapshotByTool() map[string]int {
	h.mu.Lock()
	defer h.mu.Unlock()
	out := make(map[string]int, len(h.byBot))
	for _, c := range h.byBot {
		tool := c.tool
		if tool == "" {
			tool = "tool_loop"
		}
		out[tool]++
	}
	return out
}

// dispatchToolCall sends a tool_call to the agent attached to this
// bot and waits up to agentToolCallTimeout for the result.
// Caller-supplied id should be unique per call (we generate via
// generateResourceID at the call site).
func (h *agentHub) dispatchToolCall(botUserID, callID, tool string, args map[string]any) (*agentToolResult, error) {
	conn := h.lookup(botUserID)
	if conn == nil {
		return nil, errAgentNotAttached
	}
	payload, err := json.Marshal(agentToolCall{
		Kind: "tool_call",
		ID:   callID,
		Tool: tool,
		Args: args,
	})
	if err != nil {
		return nil, err
	}
	resultCh := conn.trackPending(callID)
	select {
	case conn.send <- payload:
	case <-conn.close:
		return nil, errAgentDisconnected
	case <-time.After(5 * time.Second):
		return nil, errAgentSendTimeout
	}
	select {
	case r := <-resultCh:
		return &r, nil
	case <-conn.close:
		return nil, errAgentDisconnected
	case <-time.After(agentToolCallTimeout):
		conn.pendingMu.Lock()
		delete(conn.pending, callID)
		conn.pendingMu.Unlock()
		return nil, errAgentTimeout
	}
}

// dispatchChatMessage sends a chat_message envelope to the agent
// (kimi-cli passthrough mode) and waits for the chat_reply. Long
// timeout — kimi can take a few minutes on big tasks.
// workdirSubpath, if non-empty, tells the agent to scope the tool's
// cwd to $workdir/<subpath>; pickup uses this for project isolation.
// gitRemoteURL, if non-empty, asks the agent to do pre/post git
// plumbing around the tool run (commit + push coder output).
func (h *agentHub) dispatchChatMessage(botUserID string, threadID int64, content, workdirSubpath, gitRemoteURL string) (*agentChatReply, error) {
	conn := h.lookup(botUserID)
	if conn == nil {
		return nil, errAgentNotAttached
	}
	if !conn.hasPassthrough() {
		return nil, errAgentNoKimiCapability
	}
	id := generateResourceID()
	payload, err := json.Marshal(agentChatMessage{
		Kind:           "chat_message",
		ID:             id,
		ThreadID:       threadID,
		Content:        content,
		WorkdirSubpath: workdirSubpath,
		GitRemoteURL:   gitRemoteURL,
	})
	if err != nil {
		return nil, err
	}
	resultCh := conn.trackChatPending(id)
	select {
	case conn.send <- payload:
	case <-conn.close:
		return nil, errAgentDisconnected
	case <-time.After(5 * time.Second):
		return nil, errAgentSendTimeout
	}
	select {
	case r := <-resultCh:
		return &r, nil
	case <-conn.close:
		return nil, errAgentDisconnected
	case <-time.After(agentChatTimeout):
		conn.chatPendingMu.Lock()
		delete(conn.chatPending, id)
		conn.chatPendingMu.Unlock()
		return nil, errAgentTimeout
	}
}

// ---- host module skill dispatch (P1c.3) -----------------------------------

// skillStartEnvelope is the dock → agent dispatch frame for a host
// skill execution. Mirror of cmd/polar-agent/loop.go's struct so the
// agent can unmarshal directly.
type skillStartEnvelope struct {
	Kind      string         `json:"kind"` // "skill.start"
	RunID     int64          `json:"run_id"`
	SkillKind string         `json:"skill_kind"`
	Config    map[string]any `json:"config"`
}

// skillEventFrame is the agent → dock event the dispatcher waits on.
// EventKind is one of state/log/exit; Data carries kind-specific keys
// (see skills.Event in cmd/polar-agent/skills/skill.go for the shape).
type skillEventFrame struct {
	Kind      string         `json:"kind"` // "skill.event"
	RunID     int64          `json:"run_id"`
	EventKind string         `json:"event_kind"`
	Data      map[string]any `json:"data,omitempty"`
}

// trackSkillPending registers a per-run buffered channel that the WS
// read loop will push every skill.event for that run_id onto. Caller
// owns cleanup via untrackSkillPending — typically defer'd in
// dispatchSkillStart so an exit-or-timeout-or-disconnect path always
// releases the map entry.
func (c *agentConn) trackSkillPending(runID int64) chan skillEventFrame {
	ch := make(chan skillEventFrame, 16)
	c.skillPendingMu.Lock()
	c.skillPending[runID] = ch
	c.skillPendingMu.Unlock()
	return ch
}

func (c *agentConn) untrackSkillPending(runID int64) {
	c.skillPendingMu.Lock()
	delete(c.skillPending, runID)
	c.skillPendingMu.Unlock()
}

// deliverSkillEvent routes one frame onto the matching run's channel.
// Drops the frame (logs once) when the consumer is gone — the
// alternative (block) would wedge the WS read loop indefinitely.
func (c *agentConn) deliverSkillEvent(ev skillEventFrame) {
	c.skillPendingMu.Lock()
	ch, ok := c.skillPending[ev.RunID]
	c.skillPendingMu.Unlock()
	if !ok {
		return
	}
	select {
	case ch <- ev:
	default:
		// Channel full — consumer is slow or absent. Drop silently;
		// the consumer will get the next event we successfully push,
		// and exit events are small.
	}
}

// trackSkillStdout / untrackSkillStdout / deliverSkillStdout — P2.
// Mirrors trackSkillPending but for byte streams (bigger buffer,
// drops on full instead of blocking, separate map so lifecycle
// events don't get stuck behind a slow xterm consumer).
func (c *agentConn) trackSkillStdout(runID int64) chan []byte {
	ch := make(chan []byte, 256)
	c.skillStdoutMu.Lock()
	c.skillStdoutPending[runID] = ch
	c.skillStdoutMu.Unlock()
	return ch
}

func (c *agentConn) untrackSkillStdout(runID int64) {
	c.skillStdoutMu.Lock()
	delete(c.skillStdoutPending, runID)
	c.skillStdoutMu.Unlock()
}

func (c *agentConn) deliverSkillStdout(runID int64, chunk []byte) {
	c.skillStdoutMu.Lock()
	ch, ok := c.skillStdoutPending[runID]
	c.skillStdoutMu.Unlock()
	if !ok {
		return
	}
	select {
	case ch <- chunk:
	default:
		// Channel full — drop bytes. The bridge logs an overflow
		// counter; xterm tolerates dropouts under adversarial load
		// better than the WS read loop tolerates being wedged.
	}
}

// dispatchSkillStdin (P2 Shell): send a stdin byte chunk to the agent.
// Caller provides raw bytes; we base64-wrap in the JSON envelope.
func (h *agentHub) dispatchSkillStdin(conn *agentConn, runID int64, data []byte) error {
	if conn == nil {
		return errAgentNotAttached
	}
	frame := map[string]any{
		"kind":      "skill.stdin",
		"run_id":    runID,
		"bytes_b64": base64.StdEncoding.EncodeToString(data),
	}
	payload, err := json.Marshal(frame)
	if err != nil {
		return err
	}
	select {
	case conn.send <- payload:
		return nil
	case <-conn.close:
		return errAgentDisconnected
	case <-time.After(5 * time.Second):
		return errAgentSendTimeout
	}
}

// dispatchSkillResize (P2 Shell): forward a TIOCSWINSZ to the agent's
// pty via skill.resize.
func (h *agentHub) dispatchSkillResize(conn *agentConn, runID int64, rows, cols uint16) error {
	if conn == nil {
		return errAgentNotAttached
	}
	frame := map[string]any{
		"kind":   "skill.resize",
		"run_id": runID,
		"rows":   rows,
		"cols":   cols,
	}
	payload, err := json.Marshal(frame)
	if err != nil {
		return err
	}
	select {
	case conn.send <- payload:
		return nil
	case <-conn.close:
		return errAgentDisconnected
	case <-time.After(5 * time.Second):
		return errAgentSendTimeout
	}
}

// dispatchSkillStop (P2 Shell): explicit Run termination. The
// browser-closed defer in the bridge calls this so bash gets
// SIGTERM'd even on an abrupt disconnect.
func (h *agentHub) dispatchSkillStop(conn *agentConn, runID int64, reason string) error {
	if conn == nil {
		return errAgentNotAttached
	}
	frame := map[string]any{
		"kind":   "skill.stop",
		"run_id": runID,
		"reason": reason,
	}
	payload, err := json.Marshal(frame)
	if err != nil {
		return err
	}
	select {
	case conn.send <- payload:
		return nil
	case <-conn.close:
		return errAgentDisconnected
	case <-time.After(5 * time.Second):
		return errAgentSendTimeout
	}
}

// dispatchSkillStart sends a skill.start envelope to the agent on the
// given hostID. Caller is responsible for trackSkillPending +
// untrackSkillPending bracketing.
func (h *agentHub) dispatchSkillStart(conn *agentConn, env skillStartEnvelope) error {
	if conn == nil {
		return errAgentNotAttached
	}
	payload, err := json.Marshal(env)
	if err != nil {
		return err
	}
	select {
	case conn.send <- payload:
		return nil
	case <-conn.close:
		return errAgentDisconnected
	case <-time.After(5 * time.Second):
		return errAgentSendTimeout
	}
}

// lookupByHostID returns the live agentConn for a host's
// agent_token_id. Returns nil when no agent is currently attached
// for that host. Linear scan over byBot is fine — the typical box
// runs <10 attached agents.
func (h *agentHub) lookupByHostID(hostID string) *agentConn {
	h.mu.Lock()
	defer h.mu.Unlock()
	for _, c := range h.byBot {
		if c.hostID == hostID {
			return c
		}
	}
	return nil
}

// lookupByTokenID is the same scan but keyed on agent_token_id. Used
// during the WS handshake to resolve host_id before hostID is cached
// on the conn struct. Same linear-scan complexity reasoning.
func (h *agentHub) lookupByTokenID(tokenID string) *agentConn {
	h.mu.Lock()
	defer h.mu.Unlock()
	for _, c := range h.byBot {
		if c.tokenID == tokenID {
			return c
		}
	}
	return nil
}

// agentResearchTask is the fire-and-forget envelope used to push a
// research-mode task to a polar-agent. The agent acks lifecycle via
// HTTP callback (POST /research/runs/:id/start, /result), not via WS,
// so dispatchResearchTask returns as soon as the WS send succeeds.
type agentResearchTask struct {
	Kind          string                  `json:"kind"` // "research_task"
	ResearchRunID int64                   `json:"research_run_id"`
	ProjectID     string                  `json:"project_id"`
	TaskID        string                  `json:"task_id,omitempty"`
	TaskTitle     string                  `json:"task_title,omitempty"`
	ChatThreadID  int64                   `json:"chat_thread_id,omitempty"`
	LLMThreadID   int64                   `json:"llm_thread_id,omitempty"`
	Workdir       string                  `json:"workdir,omitempty"`
	GitRemoteURL  string                  `json:"git_remote_url,omitempty"`
	TaskContent   string                  `json:"task_content"`
	LLM           agentResearchLLMSnapshot `json:"llm"`
	CallbackToken string                  `json:"callback_token,omitempty"`
}

type agentResearchLLMSnapshot struct {
	ConfigID int64  `json:"config_id,omitempty"`
	Name     string `json:"name"`
	Model    string `json:"model"`
	Provider string `json:"provider,omitempty"`
	BaseURL  string `json:"base_url"`
	APIKey   string `json:"api_key"`
	// ProxyURL: optional HTTP(S) proxy the agent should route the
	// upstream LLM call through. Empty = direct. Plumbed from the
	// LLMConfig.ProxyURL column. The agent must NOT route its dock
	// callback / WS traffic through this proxy — it's only for the
	// LLM endpoint. polar-agent's llm_client builds a per-request
	// Proxy func that bypasses the dock host explicitly.
	ProxyURL string `json:"proxy_url,omitempty"`
}

// dispatchResearchTask hands the task envelope to the agent over WS
// and returns immediately on send. Lifecycle reporting (running →
// succeeded/failed) flows back via HTTP, not WS — so we don't track a
// pending channel here.
func (h *agentHub) dispatchResearchTask(botUserID string, task agentResearchTask) error {
	conn := h.lookup(botUserID)
	if conn == nil {
		return errAgentNotAttached
	}
	task.Kind = "research_task"
	payload, err := json.Marshal(task)
	if err != nil {
		return err
	}
	select {
	case conn.send <- payload:
		return nil
	case <-conn.close:
		return errAgentDisconnected
	case <-time.After(5 * time.Second):
		return errAgentSendTimeout
	}
}

// dispatchTaskWake rings a non-blocking {"kind":"task.wake"} doorbell to the
// agent attached to botUserID, if online. Best-effort: a missed wake is harmless
// because the agent also drains the claim queue on every (re)connect.
func (h *agentHub) dispatchTaskWake(botUserID string) {
	conn := h.lookup(botUserID)
	if conn == nil {
		return
	}
	payload, err := json.Marshal(map[string]string{"kind": "task.wake"})
	if err != nil {
		return
	}
	select {
	case conn.send <- payload:
	case <-conn.close:
	case <-time.After(2 * time.Second):
	}
}

// agentChatTimeout caps how long the platform waits for a
// chat_reply. Must comfortably exceed polar-agent's own kimi
// timeout (30min default, configurable via POLAR_KIMI_TIMEOUT) so
// the polar-agent's own timeout-with-partial-content path always
// runs first — otherwise the platform abandons the request and
// any reply that does eventually arrive is dropped.
